INSERT INTO battle_phases (id, event_id, seq, name, period, start_precision, end_precision, summary, status) VALUES ('85b0c1d7-9c20-5f11-a3e6-3fae8df68dae', '2ff2e311-c95a-5795-a647-9a4005f314cc', 1, '{"zh-Hant": "上海市區開戰"}'::jsonb, '[1937-08-13,1937-08-23)'::daterange, 'day', 'day', '{"zh-Hant": "8月9日虹橋機場事件後，13日上海進入交戰狀態，中國軍以優勢兵力進攻日本租界區，日本當日決定編組上海派遣軍。"}'::jsonb, 'pending');
INSERT INTO battle_phase_citations (id, phase_id, source_id, locator, quote, quote_lang, evidence_note, accessed_on, grade, policy_version) VALUES ('9b855713-7554-5a54-b12b-0b2dbeff66f4', '85b0c1d7-9c20-5f11-a3e6-3fae8df68dae', '04309638-0839-5545-8429-06ff32dad6fc', 'JACAR C13071346000 目錄頁「内容」欄', '十三日同方面交戦状態ニ入リ', 'ja', '階段引文', '2026-11-13', 'A', 'battle-db-2026-11-13');
INSERT INTO battle_phases (id, event_id, seq, name, period, start_precision, end_precision, summary, status) VALUES ('1385b350-03f3-5a33-a180-e1b9544cc561', '2ff2e311-c95a-5795-a647-9a4005f314cc', 2, '{"zh-Hant": "日軍登陸與上海北郊膠著"}'::jsonb, '[1937-08-23,1937-10-01)'::daterange, 'day', 'day', '{"zh-Hant": "上海派遣軍8月23日於川沙鎮、吳淞棧橋附近登陸，向嘉定、大場鎮推進，但因中國軍兵力優勢與地形困難而進展受阻，9月再增援三個半師團。"}'::jsonb, 'pending');
INSERT INTO battle_phase_citations (id, phase_id, source_id, locator, quote, quote_lang, evidence_note, accessed_on, grade, policy_version) VALUES ('c2cd0fa6-9663-560e-bf66-9f93b782c222', '1385b350-03f3-5a33-a180-e1b9544cc561', '04309638-0839-5545-8429-06ff32dad6fc', 'JACAR C13071346000 目錄頁「内容」欄', '十月上旬ヨリ重点ヲ大場鎮附近ニ指向シ', 'ja', '階段引文', '2026-11-13', 'A', 'battle-db-2026-11-13');
INSERT INTO battle_phases (id, event_id, seq, name, period, start_precision, end_precision, summary, status) VALUES ('792945e6-11fe-5554-be04-69cce1cc8b9e', '2ff2e311-c95a-5795-a647-9a4005f314cc', 3, '{"zh-Hant": "大場鎮攻防與突破"}'::jsonb, '[1937-10-01,1937-11-05)'::daterange, 'day', 'day', '{"zh-Hant": "日軍10月上旬起以大場鎮為主攻方向，戰況長期膠著，至10月下旬才取得進展，隨即向蘇州河追擊。"}'::jsonb, 'pending');
